-- Expected schema. Totals are in one currency.
CREATE TABLE IF NOT EXISTS sales_orders (
  id bigserial PRIMARY KEY,
  customer text NOT NULL,
  ordered_at timestamptz NOT NULL,
  total numeric(12,2) NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS sales_order_items (
  id bigserial PRIMARY KEY,
  order_id bigint NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,
  product text NOT NULL,
  qty integer NOT NULL,
  amount numeric(12,2) NOT NULL
);
CREATE INDEX IF NOT EXISTS sales_orders_ordered_at ON sales_orders (ordered_at);
CREATE INDEX IF NOT EXISTS sales_orders_customer ON sales_orders (lower(customer), ordered_at);
CREATE INDEX IF NOT EXISTS sales_order_items_order ON sales_order_items (order_id);
SELECT 'tables ready' AS status;

-- DEMO DATA, optional. Runs only while sales_orders is empty, so it never mixes with real orders.
INSERT INTO sales_orders (customer, ordered_at, total)
SELECT 'Demo Customer ' || lpad((1 + floor(random() * 60))::int::text, 2, '0'),
       now() - power(random(), 1.3) * interval '800 days', 0
FROM generate_series(1, 100000)
WHERE NOT EXISTS (SELECT 1 FROM sales_orders);
INSERT INTO sales_order_items (order_id, product, qty, amount)
SELECT order_id, product, qty, round((qty * price)::numeric, 2)
FROM (
  SELECT o.id AS order_id, 'Demo Product ' || chr(65 + floor(random() * 12)::int) AS product,
         1 + floor(random() * 4)::int AS qty, 5 + random() * 95 AS price
  FROM sales_orders o CROSS JOIN LATERAL generate_series(1, 1 + (o.id % 3)::int) g
  WHERE o.customer LIKE 'Demo Customer %' AND o.total = 0
    AND NOT EXISTS (SELECT 1 FROM sales_order_items i WHERE i.order_id = o.id)
) x;
UPDATE sales_orders o SET total = s.amount
FROM (SELECT order_id, sum(amount) AS amount FROM sales_order_items GROUP BY order_id) s
WHERE s.order_id = o.id AND o.total = 0 AND o.customer LIKE 'Demo Customer %';
ANALYZE sales_orders; ANALYZE sales_order_items;
SELECT count(*) AS demo_orders FROM sales_orders WHERE customer LIKE 'Demo Customer %';

