// Check the query string and work out the three periods. Dates are calendar days in the workflow timezone.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const page = (title, body) => '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>'
  + 'body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;background:#f5f6f8;color:#1f2933}main{max-width:1000px;margin:0 auto;padding:24px}'
  + 'h1{font-size:24px;margin:0 0 4px}h2{font-size:17px;margin:28px 0 8px}.muted{color:#616e7c}.box{background:#fff;border:1px solid #e1e4e8;border-radius:8px;padding:16px}'
  + 'form{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:16px 0}label{font-size:13px;display:flex;flex-direction:column;gap:4px}input{padding:6px 8px;border:1px solid #c5ccd3;border-radius:6px;font:inherit}'
  + 'button{padding:7px 14px;border:0;border-radius:6px;background:#1f6feb;color:#fff;font:inherit;cursor:pointer}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}'
  + '.tile .v{font-size:26px;font-weight:600;margin:4px 0}.up{color:#1a7f37}.down{color:#cf222e}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:7px 10px;border-bottom:1px solid #e1e4e8;font-size:14px}'
  + 'td.n,th.n{text-align:right}.notice{background:#fff8c5;border:1px solid #d4a72c;border-radius:8px;padding:14px}.error{background:#ffebe9;border:1px solid #cf222e;border-radius:8px;padding:14px}svg{width:100%;height:auto}'
  + '</style></head><body><main>' + body + '</main></body></html>';
const filterForm = (f) => '<form method="get"><label>From<input type="date" name="from" value="' + esc(f.from) + '"></label><label>To<input type="date" name="to" value="' + esc(f.to) + '"></label>'
  + '<label>Customer (optional)<input type="text" name="customer" value="' + esc(f.customer) + '" placeholder="All customers"></label><button type="submit">Show</button></form>';
const s = $input.first().json;
const zone = $now.zoneName;
const scheduled = !$('Sales Dashboard Webhook').isExecuted;
const currency = String(s.currency || '').trim().toUpperCase();
try { new Intl.NumberFormat('en-US', { style: 'currency', currency }); } catch (e) { throw new Error('Dashboard Settings: currency must be a 3-letter ISO code such as USD'); }
const defaultDays = Math.floor(Number(s.default_days)), maxDays = Math.floor(Number(s.max_days)), topN = Math.floor(Number(s.top_n));
if (!(defaultDays >= 1) || !(maxDays >= defaultDays) || !(topN >= 1 && topN <= 100)) throw new Error('Dashboard Settings: default_days must be 1 or more, max_days at least default_days, top_n between 1 and 100');
const q = scheduled ? {} : ($('Sales Dashboard Webhook').first().json.query || {});
const fail = (error, f) => [{ json: { valid: false, source: 'webhook', status_code: 400, error,
  html: page('Cannot show the dashboard', '<h1>' + esc(s.dashboard_title) + '</h1>' + filterForm(f) + '<div class="error"><b>Cannot show the dashboard.</b> ' + esc(error) + '</div>') } }];
const raw = {};
for (const k of ['from', 'to', 'customer', 'format']) {
  const v = q[k];
  if (Array.isArray(v) || (v !== undefined && v !== null && typeof v === 'object')) return fail('"' + k + '" was given more than once.', {});
  raw[k] = v === undefined || v === null ? '' : String(v).trim();
}
const today = $now.setZone(zone).startOf('day');
const parse = (str) => { if (!/^\d{4}-\d{2}-\d{2}$/.test(str)) return null; const d = DateTime.fromISO(str, { zone }); return d.isValid ? d.startOf('day') : null; };
let from, to;
if (scheduled) { to = today.minus({ days: 1 }); from = to.minus({ days: 6 }); }
else {
  if (raw.from && !parse(raw.from)) return fail('"from" must be a real date written as YYYY-MM-DD.', raw);
  if (raw.to && !parse(raw.to)) return fail('"to" must be a real date written as YYYY-MM-DD.', raw);
  to = raw.to ? parse(raw.to) : today;
  from = raw.from ? parse(raw.from) : to.minus({ days: defaultDays - 1 });
  if (from > to) return fail('"from" (' + raw.from + ') is after "to" (' + to.toISODate() + ').', raw);
}
const days = Math.round(to.diff(from, 'days').days) + 1;
if (days > maxDays) return fail('The period has ' + days + ' days. The longest allowed period is ' + maxDays + ' days.', raw);
if (raw.customer.length > 200) return fail('"customer" is longer than 200 characters.', raw);
const format = raw.format.toLowerCase() || 'html';
if (!['html', 'csv'].includes(format)) return fail('"format" must be html or csv.', raw);
const end = to.plus({ days: 1 });
const prevFrom = from.minus({ days }), lyFrom = from.minus({ years: 1 }), lyTo = end.minus({ years: 1 });
const label = (a, b) => a.toFormat('d LLL yyyy') + ' to ' + b.toFormat('d LLL yyyy');
return [{ json: {
  valid: true, source: scheduled ? 'schedule' : 'webhook', format, customer: raw.customer, currency, zone,
  from: from.toISODate(), to: to.toISODate(), days,
  period_label: label(from, to), prev_label: label(prevFrom, from.minus({ days: 1 })), ly_label: label(lyFrom, lyTo.minus({ days: 1 })),
  query_params: JSON.stringify({ from: from.toUTC().toISO(), to: end.toUTC().toISO(), prev_from: prevFrom.toUTC().toISO(),
    ly_from: lyFrom.toUTC().toISO(), ly_to: lyTo.toUTC().toISO(), tz: zone, customer: raw.customer, top_n: topN }),
} }];

// Turn the one-row summary from Postgres into the dashboard page, the CSV and the weekly email.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const page = (title, body) => '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>'
  + 'body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;background:#f5f6f8;color:#1f2933}main{max-width:1000px;margin:0 auto;padding:24px}'
  + 'h1{font-size:24px;margin:0 0 4px}h2{font-size:17px;margin:28px 0 8px}.muted{color:#616e7c}.box{background:#fff;border:1px solid #e1e4e8;border-radius:8px;padding:16px}'
  + 'form{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:16px 0}label{font-size:13px;display:flex;flex-direction:column;gap:4px}input{padding:6px 8px;border:1px solid #c5ccd3;border-radius:6px;font:inherit}'
  + 'button{padding:7px 14px;border:0;border-radius:6px;background:#1f6feb;color:#fff;font:inherit;cursor:pointer}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}'
  + '.tile .v{font-size:26px;font-weight:600;margin:4px 0}.up{color:#1a7f37}.down{color:#cf222e}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:7px 10px;border-bottom:1px solid #e1e4e8;font-size:14px}'
  + 'td.n,th.n{text-align:right}.notice{background:#fff8c5;border:1px solid #d4a72c;border-radius:8px;padding:14px}.error{background:#ffebe9;border:1px solid #cf222e;border-radius:8px;padding:14px}svg{width:100%;height:auto}'
  + '</style></head><body><main>' + body + '</main></body></html>';
const filterForm = (f) => '<form method="get"><label>From<input type="date" name="from" value="' + esc(f.from) + '"></label><label>To<input type="date" name="to" value="' + esc(f.to) + '"></label>'
  + '<label>Customer (optional)<input type="text" name="customer" value="' + esc(f.customer) + '" placeholder="All customers"></label><button type="submit">Show</button></form>';
const r = $input.first().json;
const v = $('Validate Request').first().json;
const s = $('Dashboard Settings').first().json;
const num = (x) => Number(x) || 0;
const money = (x) => new Intl.NumberFormat('en-US', { style: 'currency', currency: v.currency }).format(num(x));
const int = (x) => new Intl.NumberFormat('en-US').format(num(x));
const aov = (rev, ord) => num(ord) ? num(rev) / num(ord) : 0;
const change = (cur, base) => {
  cur = num(cur); base = num(base);
  if (!base) return { text: cur ? 'new (none before)' : 'no change', cls: '' };
  const p = (cur - base) / base * 100;
  return { text: (p >= 0 ? '+' : '') + p.toFixed(1) + '%', cls: p > 0 ? 'up' : p < 0 ? 'down' : '' };
};
const daily = Array.isArray(r.daily) ? r.daily : [];
const csv = 'date,orders,revenue,average_order_value\n' + daily.map((d) => [d.day, num(d.orders), num(d.revenue).toFixed(2), aov(d.revenue, d.orders).toFixed(2)].join(',')).join('\n') + '\n';
const base = { status_code: 200, source: v.source, format: v.format, csv, csv_name: 'sales-' + v.from + '-to-' + v.to + '.csv' };
const filters = { from: v.from, to: v.to, customer: v.customer };
const scope = v.customer ? 'Customer: ' + (r.customer_name || v.customer) : 'All customers';
if (!r.customer_exists) {
  return [{ json: { ...base, status_code: 400, html: page('Unknown customer', '<h1>' + esc(s.dashboard_title) + '</h1>' + filterForm(filters)
    + '<div class="error"><b>Unknown customer.</b> No order has ever been placed by "' + esc(v.customer) + '". Check the spelling or leave the field empty for all customers.</div>') } }];
}
const k = [
  ['Revenue', money(r.revenue), change(r.revenue, r.prev_revenue), change(r.revenue, r.ly_revenue)],
  ['Orders', int(r.orders), change(r.orders, r.prev_orders), change(r.orders, r.ly_orders)],
  ['Average order value', money(aov(r.revenue, r.orders)), change(aov(r.revenue, r.orders), aov(r.prev_revenue, r.prev_orders)), change(aov(r.revenue, r.orders), aov(r.ly_revenue, r.ly_orders))],
];
const tiles = '<div class="tiles">' + k.map(([name, val, p, y]) => '<div class="box tile"><div class="muted">' + name + '</div><div class="v">' + esc(val) + '</div>'
  + '<div class="' + p.cls + '">' + esc(p.text) + ' <span class="muted">vs previous period</span></div><div class="' + y.cls + '">' + esc(y.text) + ' <span class="muted">vs last year</span></div></div>').join('') + '</div>';
const maxRev = Math.max(0, ...daily.map((d) => num(d.revenue)));
const W = 900, H = 200, bw = W / Math.max(daily.length, 1);
const bars = daily.map((d, i) => { const h = maxRev ? num(d.revenue) / maxRev * H : 0;
  return '<rect x="' + (i * bw + bw * 0.1).toFixed(1) + '" y="' + (H - h + 20).toFixed(1) + '" width="' + Math.max(bw * 0.8, 0.5).toFixed(1) + '" height="' + h.toFixed(1) + '" fill="#1f6feb"><title>' + esc(d.day + ': ' + money(d.revenue) + ', ' + int(d.orders) + ' orders') + '</title></rect>'; }).join('');
const chart = '<svg viewBox="0 0 ' + W + ' ' + (H + 44) + '" role="img" aria-label="Daily revenue">' + bars
  + '<line x1="0" y1="' + (H + 20) + '" x2="' + W + '" y2="' + (H + 20) + '" stroke="#c5ccd3"/>'
  + '<text x="0" y="' + (H + 38) + '" font-size="12" fill="#616e7c">' + esc(v.from) + '</text><text x="' + W + '" y="' + (H + 38) + '" font-size="12" fill="#616e7c" text-anchor="end">' + esc(v.to) + '</text>'
  + '<text x="0" y="12" font-size="12" fill="#616e7c">max ' + esc(money(maxRev)) + ' per day</text></svg>';
const table = (head, rows) => '<table><tr>' + head.map((h, i) => '<th' + (i ? ' class="n"' : '') + '>' + h + '</th>').join('') + '</tr>'
  + rows.map((row) => '<tr>' + row.map((c, i) => '<td' + (i ? ' class="n"' : '') + '>' + esc(c) + '</td>').join('') + '</tr>').join('') + '</table>';
const custRows = (r.top_customers || []).map((c) => [c.customer, int(c.orders), money(c.revenue)]);
const prodRows = (r.top_products || []).map((p) => [p.product, int(p.qty), money(p.revenue)]);
const csvLink = '?from=' + v.from + '&to=' + v.to + (v.customer ? '&customer=' + encodeURIComponent(v.customer) : '') + '&format=csv';
const head = '<h1>' + esc(s.dashboard_title) + '</h1><div class="muted">' + esc(v.period_label) + ' (' + v.days + (v.days === 1 ? ' day, ' : ' days, ') + esc(v.zone) + ') | ' + esc(scope) + '</div>' + filterForm(filters);
const compare = '<p class="muted">Previous period: ' + esc(v.prev_label) + ' (' + esc(money(r.prev_revenue)) + '). Last year: ' + esc(v.ly_label) + ' (' + esc(money(r.ly_revenue)) + '). <a href="' + esc(csvLink) + '">Download daily totals as CSV</a></p>';
const empty = !num(r.orders);
const body = head + (empty ? '<div class="notice"><b>No orders in this period.</b> There are no orders from ' + esc(v.period_label) + (v.customer ? ' for ' + esc(r.customer_name || v.customer) : '') + '.</div>' : '')
  + '<h2>Key figures</h2>' + tiles + compare
  + (empty ? '' : '<h2>Daily revenue</h2><div class="box">' + chart + '</div><h2>Top customers</h2>' + table(['Customer', 'Orders', 'Revenue'], custRows) + '<h2>Top products</h2>' + table(['Product', 'Quantity', 'Revenue'], prodRows));
const eTable = (head, rows) => '<table cellpadding="6" style="border-collapse:collapse;font-size:14px"><tr>' + head.map((h) => '<th align="left" style="border-bottom:1px solid #ccc">' + h + '</th>').join('') + '</tr>'
  + rows.map((row) => '<tr>' + row.map((c) => '<td style="border-bottom:1px solid #eee">' + esc(c) + '</td>').join('') + '</tr>').join('') + '</table>';
const emailHtml = '<h2>' + esc(s.dashboard_title) + ': ' + esc(v.period_label) + '</h2>'
  + (empty ? '<p><b>No orders in this period.</b></p>' : '')
  + eTable(['Figure', 'This period', 'vs previous', 'vs last year'], k.map(([name, val, p, y]) => [name, val, p.text, y.text]))
  + (empty ? '' : '<h3>Top customers</h3>' + eTable(['Customer', 'Orders', 'Revenue'], custRows) + '<h3>Top products</h3>' + eTable(['Product', 'Quantity', 'Revenue'], prodRows));
return [{ json: { ...base, html: page(s.dashboard_title + ' | ' + v.period_label, body), email_html: emailHtml,
  email_subject: 'Weekly sales ' + v.period_label + ': ' + money(r.revenue) + ' (' + change(r.revenue, r.prev_revenue).text + ' vs previous week)' } }];
